import type { FixRateAiSplit, GitrelicReport } from '@gitrelic/core';

/**
 * Fills in default empty shapes for any analyzer field missing from a report.
 *
 * Reports generated by older CLI versions may predate newer analyzers — without
 * this normalization, any tab touching a missing field crashes with a TypeError
 * because the static `as GitrelicReport` cast provides no runtime safety.
 */
export function normalizeReport(raw: Partial<GitrelicReport>): GitrelicReport {
  return {
    timestamp: raw.timestamp ?? new Date().toISOString(),
    repoPath: raw.repoPath ?? '',
    repoName: raw.repoName ?? 'unknown',
    meta: {
      totalCommits: 0,
      totalFiles: 0,
      totalAuthors: 0,
      firstCommit: '',
      lastCommit: '',
      ageInDays: 0,
      primaryLanguage: 'unknown',
      branches: [],
      analyzedBranch: '',
      gitrelicVersion: '',
      ...raw.meta,
    },
    churn: raw.churn ?? {
      files: [],
      topFiles: [],
      hotspotCount: 0,
      summary: 'Not available',
    },
    busFactors: {
      files: raw.busFactors?.files ?? [],
      criticalFiles: raw.busFactors?.criticalFiles ?? [],
      overallBusFactor: raw.busFactors?.overallBusFactor ?? 0,
      // Reports without this field didn't exclude anything from ownership analysis.
      excluded: raw.busFactors?.excluded ?? { fixture: 0, generated: 0 },
      summary: raw.busFactors?.summary ?? 'Not available',
    },
    ageMap: {
      files: raw.ageMap?.files ?? [],
      medianAgeDays: raw.ageMap?.medianAgeDays ?? 0,
      // Mirrors `getAgeThresholds` in packages/core/src/analyzers/age-map.ts —
      // duplicated because browser code only does `import type` from @gitrelic/core
      // (value imports leak Node into the browser bundle). Keep these multipliers
      // in sync with core if they change.
      thresholds: raw.ageMap?.thresholds ?? {
        freshLimit: Math.round((raw.meta?.ageInDays ?? 0) * 0.08),
        agingLimit: Math.round((raw.meta?.ageInDays ?? 0) * 0.33),
        staleLimit: Math.round((raw.meta?.ageInDays ?? 0) * 0.66),
      },
      // Reports before RELIC-374 aged only the files their window touched.
      source: raw.ageMap?.source ?? 'window',
      dormantPackages: raw.ageMap?.dormantPackages ?? [],
      summary: raw.ageMap?.summary ?? 'Not available',
    },
    contributors: {
      contributors: raw.contributors?.contributors ?? [],
      activeContributors: raw.contributors?.activeContributors ?? [],
      ghostContributors: raw.contributors?.ghostContributors ?? [],
      topContributor: raw.contributors?.topContributor ?? {
        email: '',
        name: '',
        commitCount: 0,
        firstCommit: '',
        lastCommit: '',
        filesOwned: 0,
        linesChanged: 0,
        activeDays: 0,
        focusAreas: [],
        isActive: false,
        isGhost: false,
      },
      summary: raw.contributors?.summary ?? 'Not available',
      top3CommitShare: raw.contributors?.top3CommitShare ?? 0,
      newcomers90d: raw.contributors?.newcomers90d ?? 0,
    },
    // Reports written before cursedFiles became a report object carry a bare
    // array here. Lift those so old reports keep rendering instead of crashing
    // on `.files`.
    cursedFiles: normalizeCursedFiles(raw.cursedFiles),
    forensics: raw.forensics ?? {
      files: [],
      shameLeaderboard: [],
      totalShameCommits: 0,
      keywordTiers: { critical: 0, moderate: 0, mild: 0 },
      byMonth: [],
      summary: 'Not available',
    },
    // Reports from before the fix-rate analyzer. windowDays 0 marks the
    // backfill: a real report always has a window.
    fixRate: normalizeFixRate(raw.fixRate) ?? {
      files: [],
      unratedFiles: 0,
      changes: 0,
      fixedAfter: 0,
      rate: null,
      byMonth: [],
      fixCommits: 0,
      reverts: 0,
      sweepingSkipped: 0,
      blameTimeouts: 0,
      windowDays: 0,
      minChanges: 0,
      ai: NO_AI_SPLIT,
      summary: 'Not available',
    },
    parallelDev: normalizeParallelDev(raw.parallelDev),
    loc: raw.loc ?? {
      totalFiles: 0,
      totalLines: 0,
      files: [],
      languages: [],
      summary: 'Not available',
    },
    hotspots: raw.hotspots ?? {
      files: [],
      topHotspots: [],
      summary: 'Not available',
    },
    coupling: raw.coupling ?? {
      pairs: [],
      fileProfiles: [],
      topPairs: [],
      summary: 'Not available',
    },
    churnVelocity: raw.churnVelocity ?? {
      files: [],
      acceleratingFiles: [],
      summary: 'Not available',
    },
    rewriteRatio: raw.rewriteRatio ?? {
      files: [],
      topRewriters: [],
      totalInsertions: 0,
      totalDeletions: 0,
      highRewrite: 0,
      summary: 'Not available',
    },
    blastRadius: raw.blastRadius ?? {
      files: [],
      topBlasters: [],
      summary: 'Not available',
    },
    deadCode: raw.deadCode ?? {
      candidates: [],
      totalDeadFiles: 0,
      totalDeadLines: 0,
      summary: 'Not available',
    },
    testCoverage: {
      directories: raw.testCoverage?.directories ?? [],
      uncoveredDirectories: raw.testCoverage?.uncoveredDirectories ?? [],
      files: raw.testCoverage?.files ?? [],
      overallRatio: raw.testCoverage?.overallRatio ?? 0,
      summary: raw.testCoverage?.summary ?? 'Not available',
    },
    ghostFiles: {
      files: raw.ghostFiles?.files ?? [],
      totalGhostFiles: raw.ghostFiles?.totalGhostFiles ?? 0,
      ghostOwners: raw.ghostFiles?.ghostOwners ?? 0,
      ghostLoc: raw.ghostFiles?.ghostLoc ?? 0,
      tierMix: raw.ghostFiles?.tierMix ?? { trueGhost: 0, fading: 0 },
      summary: raw.ghostFiles?.summary ?? 'Not available',
    },
    knowledgeConcentration: raw.knowledgeConcentration ?? {
      singleAuthorFiles: 0,
      totalFiles: 0,
      concentrationIndex: 0,
      summary: 'Not available',
    },
    coAuthors: {
      pairs: raw.coAuthors?.pairs ?? [],
      authorStats: raw.coAuthors?.authorStats ?? [],
      totalCoAuthoredCommits: raw.coAuthors?.totalCoAuthoredCommits ?? 0,
      summary: raw.coAuthors?.summary ?? 'Not available',
      aiAssistedCommits: raw.coAuthors?.aiAssistedCommits ?? 0,
      humanAuthoredCommits: raw.coAuthors?.humanAuthoredCommits ?? 0,
      aiAdoptionPercent: raw.coAuthors?.aiAdoptionPercent ?? 0,
      aiAdoptionTier: raw.coAuthors?.aiAdoptionTier ?? 'none',
      aiAuthors: raw.coAuthors?.aiAuthors ?? [],
      humanPairs: raw.coAuthors?.humanPairs ?? [],
      filteredBotCommits: raw.coAuthors?.filteredBotCommits ?? 0,
      byMonth: (raw.coAuthors?.byMonth ?? []).map((m) =>
        m.aiAuthored === undefined ? { ...m, aiAuthored: 0 } : m,
      ),
      perAuthorMix: raw.coAuthors?.perAuthorMix ?? [],
      aiAuthoredCommits: raw.coAuthors?.aiAuthoredCommits ?? 0,
      aiTools: raw.coAuthors?.aiTools ?? [],
      aiAgents: raw.coAuthors?.aiAgents ?? [],
      packages: raw.coAuthors?.packages ?? [],
      sweepingLeftOut: raw.coAuthors?.sweepingLeftOut ?? 0,
    },
    hotspotClusters: raw.hotspotClusters ?? {
      clusters: [],
      multiSignalFiles: [],
      summary: 'Not available',
    },
    complexityTrend: raw.complexityTrend ?? {
      files: [],
      growingFiles: [],
      shrinkingFiles: [],
      summary: 'Not available',
    },
    commitTiming: {
      files: raw.commitTiming?.files ?? [],
      stressFiles: raw.commitTiming?.stressFiles ?? [],
      repoLateNightPercent: raw.commitTiming?.repoLateNightPercent ?? 0,
      repoWeekendPercent: raw.commitTiming?.repoWeekendPercent ?? 0,
      summary: raw.commitTiming?.summary ?? 'Not available',
      repoHourDayMatrix:
        raw.commitTiming?.repoHourDayMatrix ??
        Array.from({ length: 7 }, () => new Array<number>(24).fill(0)),
      highStress: raw.commitTiming?.highStress ?? 0,
      tierMix: raw.commitTiming?.tierMix ?? {
        low: 0,
        medium: 0,
        high: 0,
        critical: 0,
      },
      byMonth: raw.commitTiming?.byMonth ?? [],
      // Reports from before regularity: nothing counted, nobody regular.
      authorStress: (raw.commitTiming?.authorStress ?? []).map((a) => ({
        ...a,
        activeWeeks: a.activeWeeks ?? 0,
        weekendWeeks: a.weekendWeeks ?? 0,
        lateNightWeeks: a.lateNightWeeks ?? 0,
        lateNights: a.lateNights ?? 0,
        regularWeekends: a.regularWeekends ?? false,
        regularLateNights: a.regularLateNights ?? false,
      })),
      // Reports from before off-hours by package: nothing tested.
      offHours: raw.commitTiming?.offHours ?? {
        commits: 0,
        offHours: 0,
        rate: 0,
        minCommits: 10,
        packages: [],
      },
    },
    renameTracking: raw.renameTracking ?? {
      renames: [],
      chains: [],
      totalRenames: 0,
      filesWithRenames: 0,
      summary: 'Not available',
    },
    identities: raw.identities ?? [],
    fileClasses: raw.fileClasses ?? {},
    commits: raw.commits ?? [],
  };
}

type CursedFiles = GitrelicReport['cursedFiles'];
type CursedFile = CursedFiles['files'][number];

/**
 * Reports written before cursedFiles became a report object carry a bare
 * array; reports before per-reason points have files without a `breakdown`
 * (left empty: the split is unknown, not zero) and no near misses. Every
 * report so far drew the cursed line at 50.
 */
function normalizeCursedFiles(
  raw: Partial<CursedFiles> | CursedFile[] | undefined,
): CursedFiles {
  const report: Partial<CursedFiles> = Array.isArray(raw)
    ? { files: raw }
    : (raw ?? {});
  const withBreakdown = (f: CursedFile): CursedFile => ({
    ...f,
    breakdown: f.breakdown ?? [],
  });
  return {
    files: (report.files ?? []).map(withBreakdown),
    excludedBotFiles: report.excludedBotFiles ?? [],
    threshold: report.threshold ?? 50,
    nearMisses: (report.nearMisses ?? []).map(withBreakdown),
    summary: report.summary ?? 'Not available',
  };
}

const NO_AI_SPLIT: FixRateAiSplit = {
  changes: 0,
  fixedAfter: 0,
  versusOthers: null,
};

/** Fix rate's AI split (RELIC-372) on reports from before it. */
function normalizeFixRate(
  raw: GitrelicReport['fixRate'] | undefined,
): GitrelicReport['fixRate'] | undefined {
  if (!raw || raw.ai) return raw;
  return { ...raw, ai: NO_AI_SPLIT };
}

/**
 * Reports from before parallel dev left out sweeping commits had no pairs,
 * no left-out counts and only each file's top three windows: those stand in
 * for its windows.
 */
function normalizeParallelDev(
  raw: Partial<GitrelicReport['parallelDev']> | undefined,
): GitrelicReport['parallelDev'] {
  const withWindows = (f: GitrelicReport['parallelDev']['files'][number]) => ({
    ...f,
    windows: f.windows ?? f.topWindows ?? [],
  });
  return {
    files: (raw?.files ?? []).map(withWindows),
    hotFiles: (raw?.hotFiles ?? []).map(withWindows),
    totalParallelFiles: raw?.totalParallelFiles ?? 0,
    highParallel: raw?.highParallel ?? 0,
    tierMix: raw?.tierMix ?? { low: 0, medium: 0, high: 0, critical: 0 },
    byMonth: raw?.byMonth ?? [],
    pairs: raw?.pairs ?? [],
    leftOut: raw?.leftOut ?? { sweepingCommits: 0, botCommits: 0 },
    summary: raw?.summary ?? 'Not available',
  };
}
